## Installation

```bash
npx shadcn@latest add https://akoder.xyz/r/ask-ai.json
```

## Usage

```tsx
import { AskAI } from "@/components/ui/ask-ai";

export function Hero() {
  return (
    <AskAI
      prompt="Introduce this project and explain what makes it unique."
      label="ask an ai"
    />
