}
```

## Installation

```bash
npx shadcn@latest add https://akoder.xyz/r/command-palette.json
```

## Usage

```tsx
import { CommandPalette } from "@/components/ui/command-palette";

export function AppShell() {
  const [open, setOpen] = useState(false);

  return (
    <>
      <button onClick={() => setOpen(true)}>open palette</button>
      <CommandPalette open={open} onOpenChange={setOpen} recents />
    </>
  );
}
```

Pass `groups` for top-level actions, `pages` plus `page` ids on items for drill-down navigation, and ⌘K / Ctrl+K toggles the palette by default. Recents persist per `storageKey` when `recents` is on.

