## Usage

```tsx
import { DotProgress, ProgressBars } from "@/components/ui/progress-bars";

const milestones = [
  { id: "design", label: "design", value: 82 },
  { id: "build", label: "build", value: 64 },
  { id: "launch", label: "launch", value: 49 },
];

export function ProjectProgress() {
  return <ProgressBars items={milestones} />;
}

// Same props, dot matrix fill instead of etched rules.
export function ProjectDots() {
  return <DotProgress items={milestones} orientation="horizontal" />;
}
```
